def f(x):
    try:
        r = 10 // x
    except ZeroDivisionError:
        return 'zero'
    else:
        return 'ok:' + str(r)
print(f(2), f(0))

def conv(s):
    try:
        return int(s)
    except ValueError as e:
        return 'bad:' + str(e)
print(conv('42'), conv('x1'))

def check(n):
    try:
        assert n > 0, 'bad value'
        return 'ok'
    except AssertionError as e:
        return 'err:' + str(e)
print(check(3), check(-1))

def p(v):
